input.new_string:
// A page can come before its parent: every node is made first, then each is put under its parent in order.
const byId = new Map(pages.map((page) => [page.id, { id: page.id, title: page.title, children: [] }]))
const roots = []
for (const page of pages) {
  const node = byId.get(page.id)
  if (page.parent === null) roots.push(node)
  else byId.get(page.parent).children.push(node)
}
